using TraderRecords.Api.Domain.Enums;

namespace TraderRecords.Api.Domain.Entities;

/// <summary>
/// Transactions are immutable in v1. ClientId is generated by the future offline
/// client and is unique within a business, making retries safe.
/// AmountMinor is signed 64-bit kobo, never floating point.
/// </summary>
public sealed class Transaction
{
    public Guid Id { get; set; }

    public Guid BusinessId { get; set; }

    public Guid ClientId { get; set; }

    public TransactionType Type { get; set; }

    public long AmountMinor { get; set; }

    public string? Note { get; set; }

    public DateTime OccurredAtUtc { get; set; }

    public DateTime ReceivedAtUtc { get; set; }

    public Business Business { get; set; } = null!;
}
